import { MooddayLogo } from "@/features/moodday/moodday-logo";
import { NavigationWrapper } from "@/features/navigation/navigation-wrapper";
import { cn } from "@/lib/utils";
import {
  FileText,
  LayoutDashboard,
  LineChart,
  Pill,
  Settings,
  ShieldAlert,
  Users,
} from "lucide-react";
import { getTranslations } from "next-intl/server";
import Link from "next/link";
import type { PropsWithChildren } from "react";

type NavItem = {
  href: string;
  label: string;
  icon: React.ComponentType<{ className?: string }>;
};

export default async function PatientLayout({
  children,
}: PropsWithChildren) {
  const t = await getTranslations("nav");

  const items: NavItem[] = [
    {
      href: "/dashboard",
      label: t("items.dashboard"),
      icon: LayoutDashboard,
    },
    {
      href: "/analytics",
      label: t("items.analytics"),
      icon: LineChart,
    },
    {
      href: "/medications",
      label: t("items.medications"),
      icon: Pill,
    },
    {
      href: "/caregivers",
      label: t("items.caregivers"),
      icon: Users,
    },
    {
      href: "/reports/clinical",
      label: t("items.reports"),
      icon: FileText,
    },
  ];

  return (
    <NavigationWrapper
      logoChildren={<MooddayLogo label={t("appName")} />}
      navigationChildren={
        <nav className="flex flex-col gap-2 px-3 py-4">
          {items.map((item) => (
            <Link
              key={item.href}
              href={item.href}
              className={cn(
                "flex items-center gap-3 rounded-2xl px-4 py-3 text-sm font-semibold text-muted-foreground transition-colors",
                "hover:bg-primary/10 hover:text-primary",
              )}
            >
              <item.icon className="size-5" />
              {item.label}
            </Link>
          ))}
        </nav>
      }
      bottomNavigationChildren={
        <div className="flex flex-col gap-3">
          <Link
            href="/settings"
            className="flex items-center gap-3 rounded-2xl px-4 py-3 text-sm font-semibold text-muted-foreground transition-colors hover:bg-primary/10 hover:text-primary"
          >
            <Settings className="size-5" />
            {t("items.settings")}
          </Link>
          <Link
            href="/sos"
            className="rounded-2xl border border-emergency/20 bg-emergency-light/70 px-4 py-3 text-sm font-semibold text-emergency-dark shadow-xs transition-colors hover:bg-emergency-light"
          >
            <span className="flex items-center justify-between gap-3">
              <span className="flex items-center gap-2">
                <ShieldAlert className="size-4" />
                {t("items.sos")}
              </span>
              <span className="text-emergency font-bold">3114</span>
            </span>
          </Link>
        </div>
      }
    >
      {children}
    </NavigationWrapper>
  );
}

