import { DebugPanel } from "@/features/debug";
import { FloatingLegalFooter } from "@/features/legal/floating-legal-footer";
import { NextTopLoader } from "@/features/page/next-top-loader";
import { ServerToaster } from "@/features/server-sonner/server-toaster";
import { defaultLocale } from "@/lib/i18n";
import { getServerUrl } from "@/lib/server-url";
import { cn } from "@/lib/utils";
import { SiteConfig } from "@/site-config";
import { NextIntlClientProvider } from "next-intl";
import { getLocale, getMessages } from "next-intl/server";
import type { Metadata } from "next";
import { Geist_Mono, Inter } from "next/font/google";
import { NuqsAdapter } from "nuqs/adapters/next/app";
import { Suspense } from "react";
import "./globals.css";
import { Providers } from "./providers";

export const metadata: Metadata = {
  title: SiteConfig.title,
  description: SiteConfig.description,
  metadataBase: new URL(getServerUrl()),
};

const BodyFont = Inter({
  subsets: ["latin"],
  variable: "--font-sans",
});

const MonoFont = Geist_Mono({
  subsets: ["latin"],
  variable: "--font-mono",
});

export default function RootLayout({ children, modal }: LayoutProps<"/">) {
  return (
    <html lang={defaultLocale} className="h-full" suppressHydrationWarning>
      <body
        suppressHydrationWarning
        className={cn(
          "bg-background h-full font-sans antialiased",
          MonoFont.variable,
          BodyFont.variable,
        )}
      >
        <Suspense fallback={null}>
          <IntlLayout modal={modal}>{children}</IntlLayout>
        </Suspense>
      </body>
    </html>
  );
}

async function IntlLayout({ children, modal }: LayoutProps<"/">) {
  const locale = await getLocale();
  const messages = await getMessages();

  return (
    <NuqsAdapter>
      <NextIntlClientProvider locale={locale} messages={messages}>
        <Providers>
          <NextTopLoader
            delay={100}
            showSpinner={false}
            color="hsl(var(--primary))"
          />
          <Suspense fallback={null}>
            {children}
            {modal}
          </Suspense>
          {process.env.NODE_ENV === "production" ? null : <DebugPanel />}
          <FloatingLegalFooter />
          <Suspense>
            <ServerToaster />
          </Suspense>
        </Providers>
      </NextIntlClientProvider>
    </NuqsAdapter>
  );
}

